export const COLORING_DRAWINGS = Object.fromEntries(COLORING_SUBJECTS.map(s => [s.slug,
  s.items.map((name, i) => {
    const [ages, description, tip, activity] = DETAILS[s.slug][i]
    return { n: i + 1, name, ages, description, tip, activity }
  }),
]))

export { coloringDrawingPath } from './coloringSubjects.js'

export function findColoringDrawing(slug, n) {
  if (!Object.hasOwn(COLORING_DRAWINGS, slug) || !/^[1-9]\d*$/.test(String(n))) return null
  return COLORING_DRAWINGS[slug]?.find(drawing => String(drawing.n) === String(n)) || null
}

export const coloringDrawingTitle = drawing => `דף צביעה ${drawing.name} להדפסה — חינם`
export const coloringDrawingDescription = drawing => `${drawing.description} מומלץ לגילאי ${drawing.ages}. דף A4 להדפסה ולהורדה כ-PDF בחינם.`

